interactions.query:
query Doctor($owner0: String!, $name0: String!, $owner1: String!, $name1: String!, $owner2: String!, $name2: String!, $area: String!) {
  viewer { login }
  repo0: repository(owner: $owner0, name: $name0) { nameWithOwner hasIssuesEnabled
    labels(first: 100) { totalCount nodes { name } }
    area: labels(first: 100, query: $area) { nodes { name } }
  }
  repo1: repository(owner: $owner1, name: $name1) { nameWithOwner hasIssuesEnabled
    labels(first: 100) { totalCount nodes { name } }
    area: labels(first: 100, query: $area) { nodes { name } }
  }
  repo2: repository(owner: $owner2, name: $name2) { nameWithOwner hasIssuesEnabled
    labels(first: 100) { totalCount nodes { name } }
    area: labels(first: 100, query: $area) { nodes { name } }
  }
}
